import logging
from datetime import datetime
from uuid import uuid4
from typing import List, Optional

from codx.junior.global_settings import read_global_settings, write_global_settings
from codx.junior.workspaces.model import Workspace, WorkspaceStatus
from codx.junior.workspaces.engines.base import WorkspaceEngine
from codx.junior.workspaces.engines.compose import DockerComposeEngine

logger = logging.getLogger(__name__)


class WorkspaceManager:
    """Workspace orchestration façade: persistence + engine lifecycle."""

    def __init__(self, engine: Optional[WorkspaceEngine] = None):
        self.engine = engine or DockerComposeEngine()

    # -- persistence ----------------------------------------------------

    def list_workspaces(self) -> List[Workspace]:
        return read_global_settings().workspaces

    def get_workspace(self, workspace_id: str) -> Optional[Workspace]:
        return next((w for w in self.list_workspaces() if w.id == workspace_id), None)

    def _save(self, workspace: Workspace) -> None:
        settings = read_global_settings()
        workspace.updated_at = datetime.now().isoformat()
        for idx, w in enumerate(settings.workspaces):
            if w.id == workspace.id:
                settings.workspaces[idx] = workspace
                break
        else:
            settings.workspaces.append(workspace)
        write_global_settings(settings)

    # -- lifecycle ------------------------------------------------------

    def create_workspace(self, workspace: Workspace) -> Workspace:
        if any(w.folder_path == workspace.folder_path for w in self.list_workspaces()):
            raise ValueError(f"Workspace folder_path '{workspace.folder_path}' already exists")
        workspace.id = workspace.id or str(uuid4())
        self.engine.provision(workspace)
        self._save(workspace)
        logger.info("Workspace '%s' created (template=%s)", workspace.name, workspace.template)
        return workspace

    def update_workspace(self, workspace: Workspace, reprovision: bool = False) -> Workspace:
        if reprovision:
            self.engine.provision(workspace)
        self._save(workspace)
        return workspace

    def delete_workspace(self, workspace_id: str) -> None:
        workspace = self.get_workspace(workspace_id)
        if not workspace:
            raise ValueError("Workspace not found")
        self.engine.destroy(workspace)
        settings = read_global_settings()
        settings.workspaces = [w for w in settings.workspaces if w.id != workspace_id]
        write_global_settings(settings)

    def start_workspace(self, workspace_id: str) -> Workspace:
        workspace = self.get_workspace(workspace_id)
        if not workspace:
            raise ValueError("Workspace not found")
        self.engine.start(workspace)
        workspace.status = self.engine.status(workspace)
        self._save(workspace)
        return workspace

    def stop_workspace(self, workspace_id: str) -> Workspace:
        workspace = self.get_workspace(workspace_id)
        if not workspace:
            raise ValueError("Workspace not found")
        self.engine.stop(workspace)
        workspace.status = WorkspaceStatus.STOPPED
        self._save(workspace)
        return workspace

    def workspace_status(self, workspace_id: str) -> WorkspaceStatus:
        workspace = self.get_workspace(workspace_id)
        if not workspace:
            raise ValueError("Workspace not found")
        return self.engine.status(workspace)

    def workspace_logs(self, workspace_id: str, tail: int = 200) -> str:
        workspace = self.get_workspace(workspace_id)
        if not workspace:
            raise ValueError("Workspace not found")
        return self.engine.logs(workspace, tail=tail)

# --- Lifecycle endpoints (users with workspace access can start/stop) ------

@router.post("/workspaces/{workspace_id}/start", response_model=Workspace)
def start_workspace(workspace_id: str, user: CodxUser = Depends(get_authenticated_user)):
    workspace = _get_workspace_by_id(workspace_id)
    if not _user_has_workspace_access(user, workspace):
        raise HTTPException(status_code=403, detail="Access denied")
    try:
        return WorkspaceManager().start_workspace(workspace_id)
    except Exception as e:
        logger.error("Failed to start workspace %s: %s", workspace_id, e)
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/workspaces/{workspace_id}/stop", response_model=Workspace)
def stop_workspace(workspace_id: str, user: CodxUser = Depends(get_authenticated_user)):
    workspace = _get_workspace_by_id(workspace_id)
    if not _user_has_workspace_access(user, workspace):
        raise HTTPException(status_code=403, detail="Access denied")
    return WorkspaceManager().stop_workspace(workspace_id)


@router.get("/workspaces/{workspace_id}/status")
def workspace_status(workspace_id: str, user: CodxUser = Depends(get_authenticated_user)):
    workspace = _get_workspace_by_id(workspace_id)
    if not _user_has_workspace_access(user, workspace):
        raise HTTPException(status_code=403, detail="Access denied")
    return {"status": WorkspaceManager().workspace_status(workspace_id)}


@router.get("/workspaces/{workspace_id}/logs")
def workspace_logs(workspace_id: str, tail: int = 200, user: CodxUser = Depends(require_admin)):
    return {"logs": WorkspaceManager().workspace_logs(workspace_id, tail=tail)}


@router.get("/workspaces/templates")
def list_workspace_templates(user: CodxUser = Depends(require_admin)):
    from codx.junior.workspaces.templates import AVAILABLE_TEMPLATES
    return AVAILABLE_TEMPLATES

