## 1. Overwritten router

```py api/codx/junior/api/workspaces.py
import logging
from pathlib import Path

from fastapi import APIRouter, Body, Depends, HTTPException, Query

from codx.junior.model.model import CodxUser
from codx.junior.workspaces.model import Workspace, WorkspaceStatus
from codx.junior.workspaces.manager import WorkspaceManager
from codx.junior.workspaces.templates import AVAILABLE_TEMPLATES

# NOTE: confirm this import path — must match where your other routers get
# the auth dependencies from (see open points below).
from codx.junior.api.dependencies import get_authenticated_user, require_admin

logger = logging.getLogger(__name__)

router = APIRouter(tags=["workspaces"])


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _manager() -> WorkspaceManager:
    return WorkspaceManager()


def _get_workspace_or_404(workspace_id: str) -> Workspace:
    workspace = _manager().get_workspace(workspace_id)
    if not workspace:
        raise HTTPException(status_code=404, detail="Workspace not found")
    return workspace


def _user_has_workspace_access(user: CodxUser, workspace: Workspace) -> bool:
    """Empty user_ids means the workspace is visible to all users."""
    if "admin" in (getattr(user, "roles", None) or []):
        return True
    # NOTE: confirm whether workspace.user_ids stores usernames or user ids
    return not workspace.user_ids or user.username in workspace.user_ids


def _safe_workspace_file(workspace: Workspace, file_path: str) -> Path:
    """Resolve a file path inside the workspace dir, blocking path traversal."""
    workspace_dir = _manager().engine.workspace_dir(workspace).resolve()
    target = (workspace_dir / file_path).resolve()
    if workspace_dir != target and workspace_dir not in target.parents:
        raise HTTPException(status_code=400, detail="Invalid file path")
    return target


# ---------------------------------------------------------------------------
# Templates (declared before /{workspace_id} to avoid route shadowing)
# ---------------------------------------------------------------------------

@router.get("/workspaces/templates")
def list_workspace_templates(user: CodxUser = Depends(require_admin)):
    return AVAILABLE_TEMPLATES


# ---------------------------------------------------------------------------
# CRUD (admin-only mutations, users can list/read what they can access)
# ---------------------------------------------------------------------------

@router.get("/workspaces", response_model=list[Workspace])
def list_workspaces(user: CodxUser = Depends(get_authenticated_user)):
    return [
        w for w in _manager().list_workspaces()
        if _user_has_workspace_access(user, w)
    ]


@router.get("/workspaces/{workspace_id}", response_model=Workspace)
def get_workspace(workspace_id: str, user: CodxUser = Depends(get_authenticated_user)):
    workspace = _get_workspace_or_404(workspace_id)
    if not _user_has_workspace_access(user, workspace):
        raise HTTPException(status_code=403, detail="Access denied")
    return workspace


@router.post("/workspaces", response_model=Workspace)
def create_workspace(workspace: Workspace, user: CodxUser = Depends(require_admin)):
    try:
        return _manager().create_workspace(workspace)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        logger.exception("Failed to create workspace '%s'", workspace.name)
        raise HTTPException(status_code=500, detail=str(e))


@router.put("/workspaces", response_model=Workspace)
def update_workspace(
    workspace: Workspace,
    reprovision: bool = Query(default=False, description="Re-render template files"),
    user: CodxUser = Depends(require_admin),
):
    _get_workspace_or_404(workspace.id)
    try:
        return _manager().update_workspace(workspace, reprovision=reprovision)
    except Exception as e:
        logger.exception("Failed to update workspace '%s'", workspace.id)
        raise HTTPException(status_code=500, detail=str(e))


@router.delete("/workspaces/{workspace_id}")
def delete_workspace(workspace_id: str, user: CodxUser = Depends(require_admin)):
    _get_workspace_or_404(workspace_id)
    try:
        _manager().delete_workspace(workspace_id)
        return {"status": "deleted"}
    except Exception as e:
        logger.exception("Failed to delete workspace '%s'", workspace_id)
        raise HTTPException(status_code=500, detail=str(e))


# ---------------------------------------------------------------------------
# Lifecycle (users with workspace access can start/stop)
# ---------------------------------------------------------------------------

@router.post("/workspaces/{workspace_id}/start", response_model=Workspace)
def start_workspace(workspace_id: str, user: CodxUser = Depends(get_authenticated_user)):
    workspace = _get_workspace_or_404(workspace_id)
    if not _user_has_workspace_access(user, workspace):
        raise HTTPException(status_code=403, detail="Access denied")
    try:
        return _manager().start_workspace(workspace_id)
    except Exception as e:
        logger.exception("Failed to start workspace '%s'", workspace_id)
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/workspaces/{workspace_id}/stop", response_model=Workspace)
def stop_workspace(workspace_id: str, user: CodxUser = Depends(get_authenticated_user)):
    workspace = _get_workspace_or_404(workspace_id)
    if not _user_has_workspace_access(user, workspace):
        raise HTTPException(status_code=403, detail="Access denied")
    try:
        return _manager().stop_workspace(workspace_id)
    except Exception as e:
        logger.exception("Failed to stop workspace '%s'", workspace_id)
        raise HTTPException(status_code=500, detail=str(e))


@router.get("/workspaces/{workspace_id}/status")
def workspace_status(workspace_id: str, user: CodxUser = Depends(get_authenticated_user)):
    workspace = _get_workspace_or_404(workspace_id)
    if not _user_has_workspace_access(user, workspace):
        raise HTTPException(status_code=403, detail="Access denied")
    return {"status": _manager().workspace_status(workspace_id)}


@router.get("/workspaces/{workspace_id}/logs")
def workspace_logs(
    workspace_id: str,
    tail: int = Query(default=200, ge=1, le=5000),
    user: CodxUser = Depends(require_admin),
):
    _get_workspace_or_404(workspace_id)
    return {"logs": _manager().workspace_logs(workspace_id, tail=tail)}


# ---------------------------------------------------------------------------
# Workspace files (admin-only: compose file, Dockerfile, scripts, ...)
# ---------------------------------------------------------------------------

@router.get("/workspaces/{workspace_id}/files")
def list_workspace_files(workspace_id: str, user: CodxUser = Depends(require_admin)):
    workspace = _get_workspace_or_404(workspace_id)
    workspace_dir = _manager().engine.workspace_dir(workspace)
    if not workspace_dir.exists():
        return []
    return sorted(
        str(f.relative_to(workspace_dir))
        for f in workspace_dir.rglob("*") if f.is_file()
    )


@router.get("/workspaces/{workspace_id}/file")
def read_workspace_file(workspace_id: str, path: str, user: CodxUser = Depends(require_admin)):
    workspace = _get_workspace_or_404(workspace_id)
    target = _safe_workspace_file(workspace, path)
    if not target.is_file():
        raise HTTPException(status_code=404, detail="File not found")
    return {"path": path, "content": target.read_text()}


@router.post("/workspaces/{workspace_id}/file")
def write_workspace_file(
    workspace_id: str,
    path: str,
    content: str = Body(..., embed=True),
    user: CodxUser = Depends(require_admin),
):
    workspace = _get_workspace_or_404(workspace_id)
    target = _safe_workspace_file(workspace, path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)
    return {"path": path, "status": "saved"}
```

## 2. Updated `get_project_mounts` (Q1 applied, with `"*"` wildcard)

```py api/codx/junior/workspaces/templates.py
def get_project_mounts(workspace: Workspace) -> list[dict]:
    """
    Resolve host paths for the workspace's projects.

    Only the projects listed in workspace.project_ids are mounted — never
    the whole projects folder. project_ids == ["*"] mounts all projects.
    Projects are identity-mounted (same path inside the container) to match
    the default workspace convention.
    """
    from codx.junior.project.project_discover import find_all_projects
    all_projects = find_all_projects() or {}  # Dict[project_id, CODXJuniorSettings]

    if "*" in workspace.project_ids:
        projects = list(all_projects.values())
    else:
        projects = [
            all_projects[pid] for pid in workspace.project_ids
            if pid in all_projects
        ]

    return [
        {
            "project_id": project.project_id,
            "host_path": project.abs_project_path,
            "container_path": project.abs_project_path,
        }
        for project in projects
    ]
```

## 3. Small deltas applied to the module (backward compatibility)

Since persisted global settings may contain apps with `port: ""` and `container_name`, the app model gets a coercion validator and keeps `container_name`:

```py api/codx/junior/workspaces/model.py
from pydantic import BaseModel, Field, field_validator

class WorkspaceApp(BaseModel):
    id: str = Field(default="")
    name: str = Field(default="")
    description: str = Field(default="")
    icon: str = Field(default="")
    path: str = Field(default="", description="Public path prefix routed by Traefik")
    port: Optional[int] = Field(default=None, description="Container port serving this app")
    scheme: str = Field(default="http", description="http or https (e.g. Kasm VNC uses https)")
    is_vnc: Optional[bool] = Field(default=False)
    container_name: str = Field(default="", description="Kept for backward compatibility")
    roles: List[str] = Field(default=[])

    @field_validator("port", mode="before")
    @classmethod
    def _coerce_port(cls, value):
        # Legacy persisted data stores port as str, sometimes ""
        if value in ("", None):
            return None
        return int(value)
```

And `model/workspace.py` becomes a compatibility shim so existing imports (`codx.junior.model.workspace`) keep working:

